import unittest

from hourglass.gaps import find_gaps
from hourglass.models import Span


class GapTests(unittest.TestCase):
    def test_gaps_at_start_middle_and_end(self):
        gaps = find_gaps(
            [Span(600, 720), Span(780, 900)], Span(540, 960)
        )
        self.assertEqual(
            gaps,
            [
                "gap 09:00-10:00 (60 min)",
                "gap 12:00-13:00 (60 min)",
                "gap 15:00-16:00 (60 min)"
            ]
        )

    def test_full_coverage_has_no_gaps(self):
        worked = [Span(540, 700), Span(700, 960)]
        self.assertEqual(find_gaps(worked, Span(540, 960)), [])

    def test_span_outside_opening_hours_raises(self):
        with self.assertRaises(ValueError):
            find_gaps([Span(500, 600)], Span(540, 960))
